package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.AddressService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/addresses") public class AddressController {private final AddressService s;public AddressController(AddressService s){this.s=s;} @GetMapping public List<AddressResponse> all(Authentication a){return s.all(a);} @PostMapping public AddressResponse create(Authentication a,@Valid @RequestBody AddressRequest r){return s.create(a,r);}}